import{_ as t,o as a,c as i,am as s}from"./chunks/framework.yj4qiWdr.js";const m=JSON.parse('{"title":"Shadow Credentials vers Ransomware — Kill Chain","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/notes/shadow-credential-to-ransomware-storytime.md","filePath":"crto/liham/notes/shadow-credential-to-ransomware-storytime.md"}'),o={name:"crto/liham/notes/shadow-credential-to-ransomware-storytime.md"};function n(r,e,l,d,c,u){return a(),i("div",null,e[0]||(e[0]=[s('<h1 id="shadow-credentials-vers-ransomware-—-kill-chain" tabindex="-1">Shadow Credentials vers Ransomware — Kill Chain <a class="header-anchor" href="#shadow-credentials-vers-ransomware-—-kill-chain" aria-label="Permalink to &quot;Shadow Credentials vers Ransomware — Kill Chain&quot;">​</a></h1><h2 id="lundi-matin" tabindex="-1">Lundi matin <a class="header-anchor" href="#lundi-matin" aria-label="Permalink to &quot;Lundi matin&quot;">​</a></h2><p>Un e-mail de <strong>phishing</strong> arrive dans la boîte d’une employée des ressources humaines. Elle clique sur un lien et saisit ses credentials sur une fausse page de connexion. L’attaquant obtient son identifiant et son mot de passe, mais le compte utilise la <strong>MFA</strong> : le mot de passe seul ne suffit pas.</p><h2 id="foothold" tabindex="-1">Foothold <a class="header-anchor" href="#foothold" aria-label="Permalink to &quot;Foothold&quot;">​</a></h2><p>⚠️ <em>L’attaquant dispose également d’un foothold grâce à une macro dans la pièce jointe qu’elle a ouverte.</em></p><h2 id="enumeration" tabindex="-1">Énumération <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Énumération&quot;">​</a></h2><p>💬 <strong>L’attaquant possède désormais un accès peu privilégié à la workstation.</strong></p><p>Il lance <strong>BloodHound</strong> en arrière-plan et analyse les relations Active Directory. Il découvre que le compte de service <code>svc_backup</code> dispose du droit <strong>GenericWrite</strong> sur un objet ordinateur nommé <code>FS01</code>, le serveur de fichiers.</p><p>Il ne connaît pas le mot de passe de <code>svc_backup</code>. Dans ce scénario, il n’en a pas besoin.</p><p>👉 <strong>C’est ici qu’interviennent les Shadow Credentials.</strong></p><p>Imagine que chaque compte utilisateur ou ordinateur d’Active Directory possède un petit coffre. Habituellement, seule la clé connue du domaine permet de l’ouvrir : un secret associé au hash du mot de passe.</p><p>Microsoft a ajouté à Active Directory la fonctionnalité <strong>Key Trust</strong>, utilisée pour l’authentification sans mot de passe. Elle permet d’associer <em>une clé supplémentaire</em> à un compte. Celui-ci peut alors accepter le mot de passe d’origine <strong>ou</strong> cette nouvelle clé.</p><h2 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h2><p>Dans cette histoire, l’attaquant exploite le droit <code>GenericWrite</code> sur <code>FS01</code> pour <strong>ajouter sa propre clé</strong>, sans changer le mot de passe du compte. Aucun reset de mot de passe n’a lieu et l’activité passe inaperçue dans le scénario.</p><p>🏢 Il dispose désormais d’une clé que le serveur <code>FS01</code> peut accepter comme preuve d’identité.</p><p><strong>Il utilise cette clé pour demander un ticket Kerberos au nom de FS01.</strong></p><p>Le Domain Controller reconnaît la clé et délivre un <strong>TGT</strong>. L’attaquant récupère ensuite le <strong>hash NTLM</strong> du compte machine.</p><p>Il obtient ainsi les credentials du compte machine <code>FS01</code>, sans ouvrir de session interactive sur le serveur ni accéder directement à LSASS.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p><strong>Les comptes machines sont des identités du domaine.</strong></p><p>🧱 Avec les credentials de <code>FS01$</code>, l’attaquant réalise, dans ce scénario, une attaque de type <strong>DCSync</strong> : certains comptes disposant des permissions nécessaires peuvent demander des données de réplication au Domain Controller. Il récupère le hash <code>krbtgt</code> et plusieurs hashes de comptes Domain Admin.</p><p>Le domaine est désormais compromis dans cette histoire. Aucun brute force ni nouveau service n’a été nécessaire.</p><p><strong>Vendredi soir : déploiement du ransomware.</strong></p><h2 id="ransomware" tabindex="-1">Ransomware <a class="header-anchor" href="#ransomware" aria-label="Permalink to &quot;Ransomware&quot;">​</a></h2><p>🎯 Avec les credentials Domain Admin, l’attaquant atteint les serveurs de sauvegarde, puis ceux de production. Il supprime les <strong>Shadow Copies</strong>, chiffre les file shares et dépose une demande de rançon.</p><p>Le lundi matin suivant, 3 000 partages sont chiffrés et le serveur de sauvegarde est indisponible.</p><hr><h2 id="pourquoi-shadow-credentials-a-ete-decisif" tabindex="-1">Pourquoi Shadow Credentials a été décisif <a class="header-anchor" href="#pourquoi-shadow-credentials-a-ete-decisif" aria-label="Permalink to &quot;Pourquoi Shadow Credentials a été décisif&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Étape</th><th>Ce qui s’est passé</th></tr></thead><tbody><tr><td>Initial Access</td><td>Phishing puis foothold peu privilégié</td></tr><tr><td>Pivot</td><td>Découverte du droit <code>GenericWrite</code> sur un objet ordinateur</td></tr><tr><td><strong>Abus de Shadow Credentials</strong></td><td><strong>Ajout d’une clé sur FS01 sans modifier le mot de passe</strong></td></tr><tr><td>Escalation</td><td>Clé ajoutée → Kerberos TGT → hash NTLM du compte machine</td></tr><tr><td>Compromission du domaine</td><td>Hash machine → DCSync → hashes Domain Admin</td></tr><tr><td>Impact</td><td>Déploiement du ransomware dans le domaine</td></tr></tbody></table><hr><h2 id="l-idee-essentielle-sans-jargon" tabindex="-1">L’idée essentielle, sans jargon <a class="header-anchor" href="#l-idee-essentielle-sans-jargon" aria-label="Permalink to &quot;L’idée essentielle, sans jargon&quot;">​</a></h2><blockquote><p>Shadow Credentials ressemble à la création d’une <strong>copie d’un passe-partout</strong> grâce à une fonction prévue pour simplifier l’accès. La serrure et la clé d’origine restent inchangées : personne ne remarque forcément qu’une seconde clé existe.</p></blockquote><p>Les défenseurs surveillent les changements de mots de passe, les nouveaux comptes ou les échecs de connexion. Dans cette histoire, aucun de ces événements ne se produit : l’attaquant a simplement <em>ajouté une clé supplémentaire à un compte qu’il pouvait modifier</em>.</p><hr><h2 id="detection-et-remediation" tabindex="-1">Détection et remédiation <a class="header-anchor" href="#detection-et-remediation" aria-label="Permalink to &quot;Détection et remédiation&quot;">​</a></h2><p>La Blue Team peut notamment rechercher :</p><ul><li><code>Event ID 5136</code> — <strong>DS Object Modified</strong>, modification de l’attribut <code>msDS-KeyCredentialLink</code>.</li><li>Des requêtes <strong>Kerberos PKINIT</strong> inhabituelles pour des comptes machines.</li><li>La relation BloodHound <code>AddKeyCredentialLink</code>.</li></ul><h2 id="questions-pour-l-investigation-forensique" tabindex="-1">Questions pour l’investigation forensique <a class="header-anchor" href="#questions-pour-l-investigation-forensique" aria-label="Permalink to &quot;Questions pour l’investigation forensique&quot;">​</a></h2><h3 id="identity-access" tabindex="-1">Identity &amp; Access <a class="header-anchor" href="#identity-access" aria-label="Permalink to &quot;Identity &amp; Access&quot;">​</a></h3><ul><li>🔍 Un compte pouvait-il écrire dans l’attribut <code>KeyCredentialLink</code> d’autres objets ?</li><li>Quelle paire de clés a été créée, et par quel compte compromis a-t-elle été ajoutée ?</li><li>Quel compte a été compromis après l’Initial Access pour obtenir les permissions d’écriture ?</li><li>Quels comptes détenaient <code>GenericWrite</code> ou <code>WriteProperty</code> sur les objets utilisateurs ou ordinateurs ? Ces droits étaient-ils attendus ?</li><li>Des modifications légitimes de <code>msDS-KeyCredentialLink</code> existaient-elles déjà dans cet environnement ?</li><li>Quels comptes ont réalisé une authentification <strong>PKINIT</strong> (Certificate / Key Trust Kerberos) ? Était-ce habituel ?</li></ul><h3 id="timeline-scope" tabindex="-1">Timeline &amp; Scope <a class="header-anchor" href="#timeline-scope" aria-label="Permalink to &quot;Timeline &amp; Scope&quot;">​</a></h3><ul><li>⚠️ Quel est le premier <code>Event ID 5136</code> concernant <code>msDS-KeyCredentialLink</code> ? Combien de temps avant le ransomware est-il survenu ?</li><li>Plusieurs objets utilisateurs ou ordinateurs ont-ils été ciblés par des Shadow Credentials, ou un seul pivot ?</li><li>Quel délai sépare l’ajout de Shadow Credentials du premier événement DCSync ? La séquence semble-t-elle automatisée ?</li></ul><h3 id="lateral-movement-privilege-escalation" tabindex="-1">Lateral Movement &amp; Privilege Escalation <a class="header-anchor" href="#lateral-movement-privilege-escalation" aria-label="Permalink to &quot;Lateral Movement &amp; Privilege Escalation&quot;">​</a></h3><ul><li>Quel DC a traité la demande de TGT PKINIT ? Son journal KDC (<code>Event ID 4768</code>) révèle-t-il une pré-authentification par certificat sur un compte machine ?</li><li>Le compte machine <code>FS01$</code> a-t-il réalisé des requêtes de réplication LDAP inhabituelles (<code>Event ID 4662</code> et GUID de réplication) ?</li><li>🔥 D’autres comptes machines ont-ils été utilisés après le premier DCSync, ou l’attaquant est-il passé directement aux credentials Domain Admin ?</li></ul><h3 id="persistence-cleanup" tabindex="-1">Persistence &amp; Cleanup <a class="header-anchor" href="#persistence-cleanup" aria-label="Permalink to &quot;Persistence &amp; Cleanup&quot;">​</a></h3><ul><li>🧩 Des clés Shadow Credentials sont-elles restées en place après l’attaque ? Vérifier les valeurs <code>msDS-KeyCredentialLink</code> dans le contexte de l’environnement.</li><li>Des Golden Tickets ou Silver Tickets ont-ils été créés à partir du hash <code>krbtgt</code> ? Vérifier les événements <code>4769</code> et les types de chiffrement inhabituels (par exemple <code>0x17</code>, RC4).</li><li>Des comptes Domain Admin ou Scheduled Tasks ont-ils été créés pour la persistence avant le ransomware ?</li></ul><h3 id="initial-access-—-phishing-chain" tabindex="-1">Initial Access — Phishing Chain <a class="header-anchor" href="#initial-access-—-phishing-chain" aria-label="Permalink to &quot;Initial Access — Phishing Chain&quot;">​</a></h3><ul><li>Quel processus a lancé la macro : <code>WINWORD.EXE</code> ou <code>EXCEL.EXE</code> ? Quel child process a été créé ?</li><li>💡 Les logs de la messagerie permettent-ils d’identifier l’expéditeur du phishing et d’éventuelles autres cibles ?</li></ul><hr><blockquote><p><a href="https://www.thehacker.recipes/ad/movement/kerberos/shadow-credentials" target="_blank" rel="noreferrer">Shadow Credentials — Hacker Recipes</a></p></blockquote>',50)]))}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
